package com.aigstudio.runtime4.renderer
import com.aigstudio.runtime4.contract.*
import org.junit.Assert.*
import org.junit.Test
private class SimStub:SimRuntimePort{var runCount=0;var stepCount=0;var resetCount=0;var displayCount=0;private var s=SimState();override fun snapshot()=s;override fun run():SimState{runCount++;s=s.copy(ready=true);return s};override fun step():SimState{stepCount++;return s};override fun reset():SimState{resetCount++;s=SimState();return s};override fun toggleDisplay():SimState{displayCount++;s=s.copy(displayMode=if(s.displayMode=="MATERIAL")"PATH" else "MATERIAL");return s}}
private class AiStub:AiRuntimePort{var last:AiCommand?=null;private var s=AiState();override fun snapshot()=s;override fun dispatch(command:AiCommand):AiDispatchResult{last=command;return AiDispatchResult(true,s)}}
class SimAiStandaloneRegression{
 @Test fun simHasAdaptiveRealControlsAndCallbacks(){val r=SimStub();val c=SimSceneController(r);listOf(1080f to 1920f,1920f to 1080f).forEach{(w,h)->val n=c.nodes(w,h,2f);assertNotNull(n.firstOrNull{it.id=="SIM.VIEWPORT"});listOf("SIM.PLAY","SIM.STEP","SIM.RESET","SIM.DISPLAY").forEach{id->val b=n.filterIsInstance<RgbGlassButtonNode>().first{it.id==id};assertTrue(b.bounds.width>=96f&&b.bounds.height>=96f)};assertEquals(VisualState.SELECTED,n.filterIsInstance<RgbGlassButtonNode>().first{it.id=="NAV.SIM"}.visualState)};c.activate("SIM.PLAY");c.activate("SIM.STEP");c.activate("SIM.RESET");c.activate("SIM.DISPLAY");assertEquals(1,r.runCount);assertEquals(1,r.stepCount);assertEquals(1,r.resetCount);assertEquals(1,r.displayCount)}
 @Test fun aiHasLocalVaultControlsAndCallbacks(){val r=AiStub();val c=AiSceneController(r);val n=c.nodes(1080f,1920f,2f);assertNotNull(n.firstOrNull{it.id=="AI.STATUS"});listOf("AI.OPEN","AI.VERIFY","AI.RESTORE").forEach{id->assertNotNull(n.firstOrNull{it.id==id})};assertEquals(VisualState.SELECTED,n.filterIsInstance<RgbGlassButtonNode>().first{it.id=="NAV.AI"}.visualState);c.activate("AI.OPEN");assertEquals(AiCommand.OpenMain,r.last);c.activate("AI.VERIFY");assertEquals(AiCommand.Verify,r.last);c.activate("AI.RESTORE");assertEquals(AiCommand.RestoreWorkingToMain,r.last)}
}
